function lab_store_safe_media(string $value, string $sourceType): ?string { $value=trim($value); if ($value===''||!preg_match('/^[\x20-\x7E]+$/',$value)||str_contains($value,'%')||str_contains($value,'://')||str_contains($value,'..')||str_contains($value,'\\')||str_contains($value,'?')||str_contains($value,'#')||str_contains($value,'//')) return null; if(str_starts_with($value,'img/'))$value='/public/'.$value; $part='[A-Za-z0-9][A-Za-z0-9._-]*(?:/[A-Za-z0-9][A-Za-z0-9._-]*)*'; $suffix='\\.(?:png|jpe?g|webp|gif)$'; $patterns=$sourceType==='normal_store'?['#^/public/img/'.$part.$suffix.'#i']:['#^/public/img/genetic/previews/'.$part.$suffix.'#i','#^/public/three\\.js/public/genetic/previews/'.$part.$suffix.'#i']; foreach($patterns as $pattern)if(preg_match($pattern,$value)===1)return $value; return null; }
try { require_once __DIR__ . '/../../../config/database.php'; $path=getDatabasePath(); if(!is_file($path)||!is_readable($path))throw new RuntimeException(); $db=new SQLite3($path,SQLITE3_OPEN_READONLY); try { if(!$db->exec('PRAGMA query_only = ON'))throw new RuntimeException(); $result=$db->query("SELECT o.source_type, CASE WHEN o.is_active=1 THEN 1 ELSE 0 END AS offer_active, s.item_name AS normal_title, s.image_url AS normal_image, CASE WHEN COALESCE(s.is_active,0)=1 THEN 1 ELSE 0 END AS normal_available, g.display_title AS genetic_title, g.preview_path AS genetic_preview, CASE WHEN g.is_active=1 AND g.is_visible=1 THEN 1 ELSE 0 END AS genetic_available FROM tbl_mouse_lp_store_offers o LEFT JOIN tbl_store_items s ON o.source_type='normal_store' AND s.item_id=o.source_item_id LEFT JOIN tbl_genetic_trait_catalog g ON o.source_type='genetic_item' AND g.catalog_id=o.source_item_id WHERE o.source_type IN ('normal_store','genetic_item') ORDER BY o.source_type ASC, o.offer_id ASC LIMIT 100"); if(!$result instanceof SQLite3Result)throw new RuntimeException(); $offers=[]; while(($row=$result->fetchArray(SQLITE3_ASSOC))!==false){$normal=$row['source_type']==='normal_store';$ref=lab_store_safe_media((string)($normal?$row['normal_image']:$row['genetic_preview']),(string)$row['source_type']);$title=trim((string)($normal?$row['normal_title']:$row['genetic_title']));$offers[]=['source_type'=>(string)$row['source_type'],'category'=>$normal?'Normal Store Item':'Genetic Item','title'=>$title===''?'Untitled item':$title,'offer_active'=>(bool)$row['offer_active'],'source_available'=>$normal?(bool)$row['normal_available']:(bool)$row['genetic_available'],'presentation_ref'=>$ref,'media_kind'=>$ref===null?'media_unavailable':'image'];}$result->finalize();echo json_encode(['success'=>true,'capability'=>'owner_control_lab_store_offers_read','version'=>1,'mode'=>'read_only','writes'=>false,'offers'=>$offers],JSON_UNESCAPED_SLASHES); } finally {$db->close();} } catch(Throwable) { error_log(